for id,title,statement,evidence,controls in [
('PFPDOMAIN-F016','Step-packet compiler cannot serialize the current exact score type','ObstructionScore normalizes phi/gamma to Fraction even for integer zero. compile_step_packet places these fields directly into json.dumps, which raises Object of type Fraction is not JSON serializable for a valid zero score. No packet or downstream verification is produced on this normal current-type path.',[ev('pfp/domain/models.py',(187,218)),ev('pfp/domain/bridge/symbol_game_packets.py',(64,104))],['PFPDOMAIN-C021']),
('PFPDOMAIN-F017','Dialogue templates assert test and solver success without corresponding evidence','generate_round_debate given a zero score emits statements that a linear solver confirmed exactness, the test suite passed and Unicode/empty-input probes succeeded. It runs none of those checks and takes no test/solver receipts. These deterministic fictional beats can enter the normal emitter as supplied character dialogue, so preserving existing beats does not turn their claims into verified evidence. Some zero-phi branches also ignore nonzero gamma/count.',[ev('pfp/domain/bridge/symbol_game_dialogue.py',(43,48),(65,70),(85,104),(117,125),(144,151)),ev('pfp/domain/bridge/symbol_game_emitter.py',(148,171))],['PFPDOMAIN-C022']),
('PFPDOMAIN-F018','Trace input/title helpers discard current frozen packet payloads','PacketEnvelopeV2 always freezes mapping payloads into typed canonical nodes. _packet_initial_input accepts only dict and thus turns both alpha and beta content in the same task into task:test; _packet_title likewise returns empty. Trace fingerprint/perception then describe a fallback label rather than original content when this orchestration path is used. Exact helper controls establish the representation mismatch; no trace was written.',[ev('pfp/domain/entities/packet_envelope.py',(155,156)),ev('pfp/domain/bridge/symbol_game_emitter.py',(156,170),(200,208)),ev('pfp/domain/bridge/symbol_game_uns_renderer.py',(142,149)),ev('pfp/domain/bridge/unified_oe_trace.py',(89,93))],['PFPDOMAIN-C023'])]:
 n['findings'].append({'id':id,'title':title,'statement':statement,'evidence':[x['path'] for x in evidence],'source_evidence':evidence,'control_ids':controls,'status':'confirmed_bounded_source_and_probe','limits':'Read-vetted source loading and exact isolated display methods on Python3.14.2. No model, native solver, external pharmacy or artifact sink invoked.'})
n['claims'].append({'id':'PFPDOMAIN-CL06','title':'Transport identity does not confer verification or authority','statement':'The typed canonical packet/candidate mechanism binds declared fields and rejects mismatched serialized IDs. It explicitly treats proposals and evaluation summaries as transport requiring independent admission/replay. Constructor-level validation is weaker than from_dict, while legacy narrative/trace layers can label zero supplied scores as exact or successful without replay. Reusable custody mechanisms must be kept separate from those display assertions and from proof of detector adequacy.','evidence':['pfp/domain/entities/packet_envelope.py','pfp/domain/entities/candidate_artifact.py','pfp/domain/bridge/trace_policy.py'],'source_evidence':[ev('pfp/domain/entities/packet_envelope.py',(1,5),(158,184),(209,276),(292,366)),ev('pfp/domain/entities/candidate_artifact.py',(74,110),(200,248)),ev('pfp/domain/bridge/trace_policy.py',(28,73))],'status':'bounded_scope_assessment'})
